// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 minSum, address logAddr) internal {
        vm.assume(minSum < type(uint256).max);
        try c.SetMinSum(minSum) {} catch { return; }
        try c.SetLogFile(logAddr) {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 before;
        try c.MinSum() returns (uint256 __r) { before = __r; } catch { return; }
        bool setMinReverted;
        try c.SetMinSum(minSum + 1) { setMinReverted = false; } catch { setMinReverted = true; }
        bool setLogReverted;
        try c.SetLogFile(logAddr) { setLogReverted = false; } catch { setLogReverted = true; }
        assertTrue(setMinReverted && setLogReverted && c.MinSum() == before);
    }

    function testFuzz_run(uint256 minSum, address logAddr) public {
        vm.assume(logAddr.code.length == 0 && uint160(logAddr) > 0xffff && logAddr != address(this) && logAddr != address(c) && logAddr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && logAddr != 0x000000000000000000636F6e736F6c652e6c6f67 && logAddr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && logAddr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(minSum, logAddr);
    }

    receive() external payable {}
}
